if($r==='admin_event_add'&&$_SERVER['REQUEST_METHOD']==='POST'){ $p=upimg('poster','event');$db->prepare('INSERT INTO event(nama_event,lokasi,tanggal,harga_tiket,kuota,deskripsi,poster) VALUES(?,?,?,?,?,?,?)')->execute([$_POST['nama_event'],$_POST['lokasi'],$_POST['tanggal'],(int)$_POST['harga_tiket'],(int)$_POST['kuota'],$_POST['deskripsi'],$p]);header('Location:?r=admin&event=1');exit; }

if($r==='delete_tari'){ $db->prepare('DELETE FROM tari WHERE id=?')->execute([(int)$_GET['id']]);header('Location:?r=admin');exit; }
if($r==='delete_event'){ $db->prepare('DELETE FROM event WHERE id=?')->execute([(int)$_GET['id']]);header('Location:?r=admin');exit; }
if($r==='comment'&&$_SERVER['REQUEST_METHOD']==='POST'){ $db->prepare('INSERT INTO komentar(tari_id,nama,isi) VALUES(?,?,?)')->execute([(int)$_POST['tari_id'],trim($_POST['nama']),trim($_POST['isi'])]);header('Location:?r=home#tari');exit; }
if($r==='fav'&&$_SERVER['REQUEST_METHOD']==='POST'){ $db->prepare('INSERT INTO favorit(tari_id,session_key) VALUES(?,?)')->execute([(int)$_POST['tari_id'],session_id()]);header('Location:?r=home#tari');exit; }

$popular=$db->query('SELECT * FROM tari ORDER BY id DESC LIMIT 6')->fetchAll();$events=$db->query('SELECT * FROM event ORDER BY tanggal ASC LIMIT 6')->fetchAll();$vote=$db->query('SELECT t.id,t.nama_tari,COUNT(v.id) vc FROM tari t LEFT JOIN vote v ON v.tari_id=t.id GROUP BY t.id ORDER BY vc DESC LIMIT 5')->fetchAll();$komentar=$db->query('SELECT k.*,t.nama_tari FROM komentar k JOIN tari t ON t.id=k.tari_id ORDER BY k.id DESC LIMIT 6')->fetchAll();
